// ---------------------------------------------------------------------------
// Environment obligations taken from the specification only.
// Everything else is left free, because the specification calls it legal:
// writes while full (overflow), reads while empty (underflow), accesses
// during a software reset (blocked, no error pulse), i_rst_n_sw low for one
// or more cycles at any time (also while busy), any i_wr_data, any threshold
// value, independent (non-simultaneous) hardware resets, asynchronous reset
// assertion at any time.
// ---------------------------------------------------------------------------

// ENV-01: i_full_thr is a static configuration input. It is written before use and does not change while the FIFO is in use (both domains out of hardware reset). (AF-3-17, AF-6.2-10, AF-7.2-04, AF-17.1.3-04, AF-20.2-07)
always @(posedge i_clk_wr)
  if (i_rst_n_wr && i_rst_n_rd && $past(i_rst_n_wr) && $past(i_rst_n_rd))
    assume ($stable(i_full_thr));

// ENV-02: i_empty_thr is a static configuration input. It is written before use and does not change while the FIFO is in use (both domains out of hardware reset). (AF-3-17, AF-6.2-10, AF-7.2-04, AF-17.1.3-04, AF-20.2-07)
always @(posedge i_clk_rd)
  if (i_rst_n_rd && i_rst_n_wr && $past(i_rst_n_rd) && $past(i_rst_n_wr))
    assume ($stable(i_empty_thr));

// ENV-03: No write starts until both domains are out of hardware reset. The producer keeps the write interface idle while either reset is asserted. (AF-20.1-05, AF-10.7.4-23, AF-12-07)
always @(posedge i_clk_wr)
  if (!i_rst_n_wr || !i_rst_n_rd)
    assume (!i_wr_en);

// ENV-04: No read starts until both domains are out of hardware reset. The consumer keeps the read interface idle while either reset is asserted. (AF-20.1-05, AF-10.7.4-23, AF-12-07)
always @(posedge i_clk_rd)
  if (!i_rst_n_rd || !i_rst_n_wr)
    assume (!i_rd_en);

// ENV-05: i_rst_n_wr is already synchronized to i_clk_wr. It is released (0->1) only at a rising edge of i_clk_wr, so the releasing edge still samples it low: low for at least one write-clock edge. Assertion stays asynchronous and unconstrained. (AF-6.2-03, AF-3-34, AF-7.3-01, AF-20.1-01)
always @($global_clock)
  if ($rose(i_rst_n_wr))
    assume ($rose(i_clk_wr));

// ENV-06: i_rst_n_rd is already synchronized to i_clk_rd. It is released (0->1) only at a rising edge of i_clk_rd, so the releasing edge still samples it low: low for at least one read-clock edge. Assertion stays asynchronous and unconstrained. (AF-6.2-03, AF-3-34, AF-7.3-02, AF-20.1-01)
always @($global_clock)
  if ($rose(i_rst_n_rd))
    assume ($rose(i_clk_rd));

// Helper: reset pairing. r_wr_hit / r_rd_hit record that the write / read
// hardware reset was asserted in the current reset window. The window closes
// (both flags cleared) once both domains have been reset and both resets are
// released. The two resets need not overlap or be asserted together.
reg  r_wr_hit = 1'b0;
reg  r_rd_hit = 1'b0;
wire w_wr_seen  = r_wr_hit | !i_rst_n_wr;
wire w_rd_seen  = r_rd_hit | !i_rst_n_rd;
wire w_rst_pend = w_wr_seen ^ w_rd_seen;  // one domain reset, the other not yet

always @($global_clock) begin
  if (w_wr_seen && w_rd_seen && i_rst_n_wr && i_rst_n_rd) begin
    r_wr_hit <= 1'b0;
    r_rd_hit <= 1'b0;
  end else begin
    r_wr_hit <= w_wr_seen;
    r_rd_hit <= w_rd_seen;
  end
end

// ENV-07: The integrator resets both domains. After a hardware reset of one domain, the producer issues no write until the other domain has also been reset and both are out of reset. The resets need not be asserted together. (AF-12-07, AF-7.2-12, AF-20.1-05, AF-20.2-27, AF-3-36, AF-7.2-11)
always @(posedge i_clk_wr)
  if (w_rst_pend)
    assume (!i_wr_en);

// ENV-08: The integrator resets both domains. After a hardware reset of one domain, the consumer issues no read until the other domain has also been reset and both are out of reset. The resets need not be asserted together. (AF-12-07, AF-7.2-12, AF-20.1-05, AF-20.2-27, AF-3-36, AF-7.2-11)
always @(posedge i_clk_rd)
  if (w_rst_pend)
    assume (!i_rd_en);
